package ringbuf

import "testing"

func TestPushPopBasic(t *testing.T) {
	rb := New[int](3)
	if err := rb.Push(1); err != nil {
		t.Fatal(err)
	}
	if err := rb.Push(2); err != nil {
		t.Fatal(err)
	}
	v, err := rb.Pop()
	if err != nil {
		t.Fatal(err)
	}
	if v != 1 {
		t.Errorf("want 1 got %d", v)
	}
}

func TestFull(t *testing.T) {
	rb := New[int](2)
	rb.Push(1)
	rb.Push(2)
	if err := rb.Push(3); err == nil {
		t.Fatal("expected error on push to full buffer")
	}
}

func TestEmpty(t *testing.T) {
	rb := New[int](2)
	if _, err := rb.Pop(); err == nil {
		t.Fatal("expected error on pop from empty buffer")
	}
}

func TestIsFullIsEmpty(t *testing.T) {
	rb := New[string](2)
	if !rb.IsEmpty() {
		t.Fatal("should be empty initially")
	}
	rb.Push("a")
	rb.Push("b")
	if !rb.IsFull() {
		t.Fatal("should be full after 2 pushes")
	}
}

func TestWrapAround(t *testing.T) {
	rb := New[int](3)
	rb.Push(1)
	rb.Push(2)
	rb.Push(3)
	rb.Pop()
	rb.Push(4)
	v, _ := rb.Pop()
	if v != 2 {
		t.Errorf("want 2 got %d", v)
	}
	v, _ = rb.Pop()
	if v != 3 {
		t.Errorf("want 3 got %d", v)
	}
	v, _ = rb.Pop()
	if v != 4 {
		t.Errorf("want 4 got %d", v)
	}
}
